import{_ as t,b as e,a as l,aS as d}from"./chunks/framework.M2Whok06.js";const a="/assets/english-02.rER6hEN1.png",c=JSON.parse('{"title":"英语音标","description":"","frontmatter":{},"headers":[],"relativePath":"note/stationmaster/english/01-英语音标.md","filePath":"note/stationmaster/english/01-英语音标.md","lastUpdated":1742736905000}'),s={name:"note/stationmaster/english/01-英语音标.md"},i=d('<h1 id="英语音标" tabindex="-1">英语音标 <a class="header-anchor" href="#英语音标" aria-label="Permalink to &quot;英语音标&quot;">​</a></h1><h2 id="音标" tabindex="-1">音标 <a class="header-anchor" href="#音标" aria-label="Permalink to &quot;音标&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">元音音标</th><th style="text-align:left;">谐音</th><th style="text-align:left;">发音技巧</th><th style="text-align:left;">辅音音标</th><th style="text-align:left;">谐音</th><th style="text-align:left;">发音技巧</th></tr></thead><tbody><tr><td style="text-align:left;">/æ/</td><td style="text-align:left;"></td><td style="text-align:left;">嘴张大，嘴角尽量拉向两边，成扁平形，舌尖抵下齿。</td><td style="text-align:left;">/b/</td><td style="text-align:left;">波</td><td style="text-align:left;">双唇紧闭，然后快速张开，让气流冲出口腔，发出爆破音声带需振动。</td></tr><tr><td style="text-align:left;">/e/</td><td style="text-align:left;"></td><td style="text-align:left;">嘴形扁平，舌尖抵下齿，舌前部稍微抬起。</td><td style="text-align:left;">/k/</td><td style="text-align:left;">可</td><td style="text-align:left;">舌后部抵住软腭，憋住气，然后突然离开将气送出来，像咳嗽一样，但声带不振动。</td></tr><tr><td style="text-align:left;">/ɪ/</td><td style="text-align:left;">一</td><td style="text-align:left;">嘴唇微微张开，舌尖抵下齿，舌前部抬高，嘴形扁平，声音短而快。</td><td style="text-align:left;">/d/</td><td style="text-align:left;">的</td><td style="text-align:left;">舌尖抵上齿龈，憋住气，然后突然弹开舌尖，让气流冲出口腔，但声带需振动。</td></tr><tr><td style="text-align:left;">/ɔː/</td><td style="text-align:left;">噢</td><td style="text-align:left;">口腔打开，嘴张大，舌头身后缩，双唇稍收圆。</td><td style="text-align:left;">/f/</td><td style="text-align:left;">浮</td><td style="text-align:left;">上齿轻轻接触下唇，然后吹气，让气流从唇齿间通过，形成摩擦，但声带不振动。</td></tr><tr><td style="text-align:left;">/ʌ/</td><td style="text-align:left;">啊</td><td style="text-align:left;">嘴巴半张，舌尖和舌端两侧贴在下。双唇向两边平展形成扁平状，震动声带，短促有力推出气流发音。</td><td style="text-align:left;">/g/</td><td style="text-align:left;">哥</td><td style="text-align:left;">舌后部抵住软腭，憋住气，舌头突然离开，将气送出来，但声带需振动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/h/</td><td style="text-align:left;">呵</td><td style="text-align:left;">舌后部抵住软腭，憋住气，舌头突然离开，将气送出来，但声带需振动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/dʒ/</td><td style="text-align:left;">只</td><td style="text-align:left;">双唇略微开突出，用力吐气，但声带需振动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/k/</td><td style="text-align:left;">可</td><td style="text-align:left;">舌后部抵住软腭，憋住气，然后突然离开，将气送出来，像咳嗽一样，但声带不振动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/l/</td><td style="text-align:left;">了</td><td style="text-align:left;">舌尖抵住上齿龈，舌尖轻微用力弯曲，气流从舌的旁边送出</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/m/</td><td style="text-align:left;">么</td><td style="text-align:left;">双唇紧闭，舌头平放，气流从鼻腔送出，声带振动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/n/</td><td style="text-align:left;">呢</td><td style="text-align:left;">双唇微开，舌尖抵上齿龈，气流从鼻孔里出来，声带振动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/p/</td><td style="text-align:left;">泼</td><td style="text-align:left;">双唇紧闭，然后快速张开，让气流冲出口腔，发出爆破音，但声带不振动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/w/</td><td style="text-align:left;"></td><td style="text-align:left;">嘴唇收小，向前突出，气流从双唇间摩擦而过，同时声带需震动，发音短促</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/r/</td><td style="text-align:left;">弱</td><td style="text-align:left;">双唇略张开并收圆，稍突出，舌尖卷起，靠近上齿龈后部，气流通过舌端及上齿龈后部形成摩擦，同时震动声带发音。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/s/</td><td style="text-align:left;">撕</td><td style="text-align:left;">上下齿自然合拢，嘴微张，抬舌尖，靠近齿龈，将气流所通过的气流通道收窄，将口腔的空气形成气流由舌端与齿龈之间的窄缝中泄出，伴有嘶嘶声。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/t/</td><td style="text-align:left;">特</td><td style="text-align:left;">嘴巴微微张开，舌尖先紧贴上齿龈，憋住气，舌尖迅速下降，使气流冲出口腔，声带不震动，只能听到气流的声音。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/v/</td><td style="text-align:left;">无</td><td style="text-align:left;">上齿轻触下嘴唇，和发[音时的口型基本相同，气流从齿之间的缝隙通过，引起摩擦，吐气较弱但声带有震动</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/w/</td><td style="text-align:left;">娃</td><td style="text-align:left;">嘴唇微张缩圆，并向前突出，上下齿分开贴住嘴唇，舌后部微抬，气流从双唇间摩擦而过，同时声带需震动，发音短促，立刻向后面的元音滑动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/j/</td><td style="text-align:left;">也</td><td style="text-align:left;">双唇向两旁伸展成扁平型，口型和[]类似。舌前部抬起但不接触上颚，让气流从舌和上颚的缝隙间通过，声带振动，发音短暂，立刻向后面的元音滑动。</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">/z/</td><td style="text-align:left;"></td><td style="text-align:left;">和[s]发音类似，声带振动。</td></tr></tbody></table><h2 id="字母音标" tabindex="-1">字母音标 <a class="header-anchor" href="#字母音标" aria-label="Permalink to &quot;字母音标&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><table tabindex="0"><thead><tr><th style="text-align:left;">大写</th><th style="text-align:left;">小写</th><th style="text-align:left;">读音</th><th style="text-align:left;">大写</th><th style="text-align:left;">小写</th><th style="text-align:left;">读音</th></tr></thead><tbody><tr><td style="text-align:left;">A</td><td style="text-align:left;">a</td><td style="text-align:left;">/eɪ/</td><td style="text-align:left;">N</td><td style="text-align:left;">n</td><td style="text-align:left;">/ɛn/</td></tr><tr><td style="text-align:left;">B</td><td style="text-align:left;">b</td><td style="text-align:left;">/bi:/</td><td style="text-align:left;">O</td><td style="text-align:left;">o</td><td style="text-align:left;">/oʊ/</td></tr><tr><td style="text-align:left;">C</td><td style="text-align:left;">c</td><td style="text-align:left;">/si:/</td><td style="text-align:left;">P</td><td style="text-align:left;">p</td><td style="text-align:left;">/piː/</td></tr><tr><td style="text-align:left;">D</td><td style="text-align:left;">d</td><td style="text-align:left;">/di:/</td><td style="text-align:left;">Q</td><td style="text-align:left;">q</td><td style="text-align:left;">/kjuː/</td></tr><tr><td style="text-align:left;">E</td><td style="text-align:left;">e</td><td style="text-align:left;">/i:/</td><td style="text-align:left;">R</td><td style="text-align:left;">r</td><td style="text-align:left;">/ɑr/</td></tr><tr><td style="text-align:left;">F</td><td style="text-align:left;">f</td><td style="text-align:left;">/ef/</td><td style="text-align:left;">S</td><td style="text-align:left;">s</td><td style="text-align:left;">/ɛs/</td></tr><tr><td style="text-align:left;">G</td><td style="text-align:left;">g</td><td style="text-align:left;">/dʒiː/</td><td style="text-align:left;">T</td><td style="text-align:left;">t</td><td style="text-align:left;">/tiː/</td></tr><tr><td style="text-align:left;">H</td><td style="text-align:left;">h</td><td style="text-align:left;">/eɪtʃ/</td><td style="text-align:left;">U</td><td style="text-align:left;">u</td><td style="text-align:left;">/juː/</td></tr><tr><td style="text-align:left;">I</td><td style="text-align:left;">i</td><td style="text-align:left;">/aɪ/</td><td style="text-align:left;">V</td><td style="text-align:left;">v</td><td style="text-align:left;">/viː/</td></tr><tr><td style="text-align:left;">J</td><td style="text-align:left;">j</td><td style="text-align:left;">/dʒeɪ/</td><td style="text-align:left;">W</td><td style="text-align:left;">w</td><td style="text-align:left;">/ˈdʌbəljuː/</td></tr><tr><td style="text-align:left;">K</td><td style="text-align:left;">k</td><td style="text-align:left;">/keɪ/</td><td style="text-align:left;">X</td><td style="text-align:left;">x</td><td style="text-align:left;">/ɛks/</td></tr><tr><td style="text-align:left;">L</td><td style="text-align:left;">l</td><td style="text-align:left;">/ɛl/</td><td style="text-align:left;">Y</td><td style="text-align:left;">y</td><td style="text-align:left;">/waɪ/</td></tr><tr><td style="text-align:left;">M</td><td style="text-align:left;">m</td><td style="text-align:left;">/ɛm/</td><td style="text-align:left;">Z</td><td style="text-align:left;">z</td><td style="text-align:left;">/ziː/</td></tr></tbody></table>',6),n=[i];function f(g,x,y,r,h,o){return l(),e("div",null,n)}const b=t(s,[["render",f]]);export{c as __pageData,b as default};
